using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "TriggerEffectAction", menuName = "Data/Battle/Battle Actions/Enchantment Actions/Trigger Effect Action")]
public class TriggerEffectAction : BattleAction
{
	[Header("Trigger Effect Action")]
	[SerializeField]
	private Effect effect;

	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	[SerializeField]
	private bool decreaseEffect;

	[SerializeField]
	[ShowIf("decreaseEffect")]
	private int decreaseEffectAmount;

	[SerializeField]
	private bool useHalfOfTheEffect;

	[SerializeField]
	private bool roundedUp;

	public Effect Effect => effect;

	public bool DecreaseEffect => decreaseEffect;

	public int DecreaseEffectAmount => decreaseEffectAmount;

	public bool UseHalfOfTheEffect => useHalfOfTheEffect;

	public bool RoundedUp => roundedUp;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return currentActiveUnits.IsAnyTargetWithEffect(effect);
	}

	public override bool CheckCondition(GameObject target, int actionValue)
	{
		return target.GetComponent<UnitEffects>().IsEffectActive(effect, activateFeedback: false);
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		DefaultCast(target, source);
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		for (int i = 0; i < targets.Count; i++)
		{
			targets[i].GetComponent<UnitEffects>().IsEffectActiveWithOptionalActivation(effect, activateFeedback: false, updateAmount: false);
		}
		ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState(WaitForFramesType.WaitToUpdateCorruptionFrames);
	}

	protected void DefaultCast(GameObject target, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		target.GetComponent<UnitEffects>().IsEffectActiveWithOptionalActivation(effect, activateFeedback: false, updateAmount: false);
		ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState(WaitForFramesType.WaitToUpdateCorruptionFrames);
	}
}
